== Usage ==
{{ItemInfo
|rarity = legendary
|item_ability_name = Time Warp
|item_ability_activation = RIGHT CLICK
|item_ability_description = Advance time by {{pink|1 hour}}! <br><br>Impacts your Minions, Chocolate Factory, Aging Items, Kat, Fann, Greenhouse, and The Forge.
|item_ability_cooldown = 48h
